import Foundation

/// Interprets the leading reasoning block without modifying saved history.
/// A standalone closing tag also supports older Qwen messages whose opening
/// tag was supplied by the chat template rather than generated by the model.
struct AssistantMessageContent: Equatable, Sendable {
    let reasoning: String?
    let answer: String
    let isThinking: Bool

    init(_ source: String, streaming: Bool = false) {
        let trimmed = source.drop(while: { $0.isWhitespace })
        let opening = "<think>"
        let closing = "</think>"
        if trimmed.hasPrefix(opening) {
            let body = String(trimmed.dropFirst(opening.count))
            if let end = Self.delimiter(closing, in: body) {
                reasoning = String(body[..<end.lowerBound]).trimmingCharacters(in: .whitespacesAndNewlines)
                answer = String(body[end.upperBound...]).trimmingCharacters(in: .whitespacesAndNewlines)
                isThinking = false
            } else {
                var visible = body
                // A token/chunk can stop halfway through the closing delimiter.
                for length in stride(from: closing.count - 1, through: 1, by: -1) {
                    let prefix = String(closing.prefix(length))
                    if visible.hasSuffix(prefix), let range = Self.delimiter(prefix, in: visible),
                       range.upperBound == visible.endIndex {
                        visible = String(visible[..<range.lowerBound])
                        break
                    }
                }
                reasoning = visible.trimmingCharacters(in: .whitespacesAndNewlines)
                answer = ""
                isThinking = true
            }
        } else if let end = Self.delimiter(closing, in: source, standalone: true) {
            reasoning = String(source[..<end.lowerBound]).trimmingCharacters(in: .whitespacesAndNewlines)
            answer = String(source[end.upperBound...]).trimmingCharacters(in: .whitespacesAndNewlines)
            isThinking = false
        } else if streaming, !trimmed.isEmpty, opening.hasPrefix(trimmed) {
            reasoning = ""
            answer = ""
            isThinking = true
        } else {
            reasoning = nil
            answer = source
            isThinking = false
        }
    }

    /// Complete a template-prefilled opening tag for App messages. Raw API
    /// output and model token counts remain unchanged unless explicitly enabled.
    static func framed(_ text: String, primed: Bool) -> String {
        guard primed, !text.isEmpty else { return text }
        let trimmed = text.drop(while: { $0.isWhitespace })
        if trimmed.hasPrefix("<think>") || (!trimmed.isEmpty && "<think>".hasPrefix(trimmed)) { return text }
        return "<think>\n" + text
    }

    /// Protocol delimiters inside Markdown code or escaped text are literals.
    private static func delimiter(_ marker: String, in text: String, standalone: Bool = false) -> Range<String.Index>? {
        var fence: (character: Character, count: Int)?
        var inlineTicks = 0
        var lineStart = text.startIndex
        while lineStart < text.endIndex {
            let lineEnd = text[lineStart...].firstIndex(of: "\n") ?? text.endIndex
            let line = text[lineStart..<lineEnd]
            let trimmed = line.drop(while: { $0 == " " || $0 == "\t" || $0 == "\r" })
            let indentation = line.distance(from: line.startIndex, to: trimmed.startIndex)
            if let active = fence {
                let count = trimmed.prefix(while: { $0 == active.character }).count
                if count >= active.count && trimmed.dropFirst(count).allSatisfy({ $0.isWhitespace }) { fence = nil }
            } else if indentation < 4, let first = trimmed.first, first == "`" || first == "~",
                      trimmed.prefix(while: { $0 == first }).count >= 3, inlineTicks == 0 {
                fence = (first, trimmed.prefix(while: { $0 == first }).count)
            } else if indentation < 4 || inlineTicks != 0 {
                var index = line.startIndex
                while index < line.endIndex {
                    let character = line[index]
                    if character == "\\", inlineTicks == 0 {
                        index = line.index(after: index)
                        if index < line.endIndex { index = line.index(after: index) }
                        continue
                    }
                    if character == "`" {
                        let count = line[index...].prefix(while: { $0 == "`" }).count
                        if inlineTicks == 0 { inlineTicks = count }
                        else if inlineTicks == count { inlineTicks = 0 }
                        index = line.index(index, offsetBy: count)
                        continue
                    }
                    if inlineTicks == 0, line[index...].hasPrefix(marker),
                       !standalone || line.trimmingCharacters(in: .whitespacesAndNewlines) == marker {
                        return index..<text.index(index, offsetBy: marker.count)
                    }
                    index = line.index(after: index)
                }
            }
            lineStart = lineEnd < text.endIndex ? text.index(after: lineEnd) : text.endIndex
        }
        return nil
    }
}
